class Solution {
  public long maximizeSumOfWeights(int[][] edges, int k) {
    int n = edges.length + 1;
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)], w = new int[2 * (n - 1)];
    for (int[] e : edges) {
      int p = start[e[0]] + fill[e[0]]++;
      to[p] = e[1];
      w[p] = e[2];
      p = start[e[1]] + fill[e[1]]++;
      to[p] = e[0];
      w[p] = e[2];
    }
    int[] order = new int[n], par = new int[n];
    par[0] = -1;
    int head = 0, tail = 0;
    order[tail++] = 0;
    while (head < tail) {
      int u = order[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        if (to[p] != par[u]) {
          par[to[p]] = u;
          order[tail++] = to[p];
        }
      }
    }
    long[] dp0 = new long[n], dp1 = new long[n];
    long[] gains = new long[n];
    for (int idx = n - 1; idx >= 0; idx--) {
      int u = order[idx], m = 0;
      long base = 0;
      for (int p = start[u]; p < start[u + 1]; p++) {
        int c = to[p];
        if (c == par[u]) continue;
        base += dp0[c];
        long g = dp1[c] + w[p] - dp0[c];
        if (g > 0) gains[m++] = g;
      }
      java.util.Arrays.sort(gains, 0, m);
      long s0 = base, s1 = base;
      for (int i = 0; i < Math.min(m, k); i++) {
        long g = gains[m - 1 - i];
        s0 += g;
        if (i < k - 1) s1 += g;
      }
      dp0[u] = s0;
      dp1[u] = s1;
    }
    return dp0[0];
  }
}
